<script setup lang="ts">
import { computed, ref } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'

const voiceStore = useVoiceStore()
const entries = computed(() => voiceStore.connectionDiagnostics)
const expanded = ref(true)
const copied = ref(false)

async function copyDiagnostics() {
  const report = entries.value.join('\n')
  try {
    await navigator.clipboard.writeText(report)
  } catch {
    const field = document.createElement('textarea')
    field.value = report
    document.body.appendChild(field)
    field.select()
    document.execCommand('copy')
    field.remove()
  }
  copied.value = true
  window.setTimeout(() => { copied.value = false }, 1500)
}
</script>

<template>
  <aside class="diagnostics" aria-label="Live-Verbindungsprotokoll">
    <header class="toolbar">
      <button class="toggle" type="button" @click="expanded = !expanded">
        {{ expanded ? '▼' : '▲' }} Live-Verbindungslog ({{ entries.length }})
      </button>
      <button type="button" :disabled="!entries.length" @click="copyDiagnostics">
        {{ copied ? 'Kopiert' : 'Kopieren' }}
      </button>
      <button type="button" :disabled="!entries.length" @click="voiceStore.clearConnectionDiagnostics()">
        Leeren
      </button>
    </header>
    <section v-if="expanded" class="log-content" aria-live="polite">
      <p>Browser-WebRTC-Protokoll, lokal gespeichert (max. 500 Zeilen). Keine IP-Adressen oder Audiodaten.</p>
      <pre>{{ entries.length ? entries.join('\n') : 'Warte auf Verbindungsereignisse …' }}</pre>
    </section>
  </aside>
</template>

