import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type {
  VoiceState,
  VoiceSettings,
  PeerConnectionState,
  AudioDeviceInfo,
  Vec3
} from '@/types'
import { ServerVoiceConnection } from '@/voice/ServerVoiceConnection'
import { PeerJsVoiceConnection } from '@/voice/PeerJsVoiceConnection'
import { createSilentAudioStream } from '@/audio/SilentAudioStream'

let serverConnection: ServerVoiceConnection | null = null
let peerJsConnection: PeerJsVoiceConnection | null = null
let remoteAudio: HTMLAudioElement | null = null
let closeSilentAudio: (() => void) | null = null

export interface TestChatMessage {
  id: string
  playerName: string
  message: string
  receivedAt: number
}

export const useVoiceStore = defineStore('voice', () => {
  const state = ref<VoiceState>({
    isConnected: false,
    isConnecting: false,
    isMuted: false,
    isDeafened: false,
    currentChannel: null,
    peers: new Map(),
    localStream: null,
    microphoneWarning: null,
    volume: 1.0,
    noiseSuppressionEnabled: true,
    noiseSuppressionLevel: 0.5,
    spatialAudioEnabled: true,
  })

  const settings = ref<VoiceSettings>({
    inputDeviceId: '',
    outputDeviceId: '',
    inputVolume: 1.0,
    outputVolume: 1.0,
    noiseSuppression: true,
    noiseSuppressionLevel: 0.5,
    echoCancellation: true,
    autoGainControl: true,
    spatialAudio: true,
    pushToTalk: false,
    pushToTalkKey: 'KeyV',
    voiceActivationThreshold: -40,
  })

  const connectionState = ref<PeerConnectionState>({
    peerId: 'local',
    iceConnectionState: 'new',
    connectionState: 'new',
    signalingState: 'stable',
    isMuted: false,
    isDeafened: false,
    volume: 1.0,
    position: undefined,
    lastActivity: Date.now(),
  })

  const availableInputDevices = ref<AudioDeviceInfo[]>([])
  const availableOutputDevices = ref<AudioDeviceInfo[]>([])
  const connectionDiagnostics = ref<string[]>(loadConnectionDiagnostics())
  const testChatMessages = ref<TestChatMessage[]>([])
  const testChatConnected = ref(false)

  const connectedPeers = computed(() =>
    Array.from(state.value.peers.values()).filter(p => p.connectionState === 'connected')
  )

  const peerCount = computed(() => state.value.peers.size)
  const isInChannel = computed(() => !!state.value.currentChannel)

  function setConnected(connected: boolean) {
    state.value.isConnected = connected
    if (connected) {
      state.value.isConnecting = false
    }
  }

  function setConnecting(connecting: boolean) {
    state.value.isConnecting = connecting
  }

  function setMuted(muted: boolean) {
    state.value.isMuted = muted
  }

  function setDeafened(deafened: boolean) {
    state.value.isDeafened = deafened
  }

  function setCurrentChannel(channelId: string | null) {
    state.value.currentChannel = channelId
  }

  function addPeer(peerId: string, peerState: PeerConnectionState) {
    state.value.peers.set(peerId, peerState)
  }

  function removePeer(peerId: string) {
    state.value.peers.delete(peerId)
  }

  function updatePeer(peerId: string, updates: Partial<PeerConnectionState>) {
    const peer = state.value.peers.get(peerId)
    if (peer) {
      state.value.peers.set(peerId, { ...peer, ...updates })
    }
  }

  function setLocalStream(stream: MediaStream | null) {
    state.value.localStream = stream
  }

  function setVolume(volume: number) {
    state.value.volume = Math.max(0, Math.min(1, volume))
  }

  function setNoiseSuppressionEnabled(enabled: boolean) {
    state.value.noiseSuppressionEnabled = enabled
    settings.value.noiseSuppression = enabled
  }

  function setNoiseSuppressionLevel(level: number) {
    state.value.noiseSuppressionLevel = Math.max(0, Math.min(1, level))
    settings.value.noiseSuppressionLevel = state.value.noiseSuppressionLevel
  }

  function setSpatialAudioEnabled(enabled: boolean) {
    state.value.spatialAudioEnabled = enabled
    settings.value.spatialAudio = enabled
  }

  function updateConnectionState(stateUpdate: Partial<PeerConnectionState>) {
    connectionState.value = { ...connectionState.value, ...stateUpdate }
  }

  function setInputDevices(devices: AudioDeviceInfo[]) {
    availableInputDevices.value = devices
  }

  function setOutputDevices(devices: AudioDeviceInfo[]) {
    availableOutputDevices.value = devices
  }

  function addConnectionDiagnostic(message: string) {
    const entry = `${new Date().toISOString()} ${message}`
    connectionDiagnostics.value = [...connectionDiagnostics.value.slice(-499), entry]
    try {
      localStorage.setItem('svc-connection-diagnostics', JSON.stringify(connectionDiagnostics.value))
    } catch { /* Keep the live log available when storage is unavailable or full. */ }
  }

  function clearConnectionDiagnostics() {
    connectionDiagnostics.value = []
    try { localStorage.removeItem('svc-connection-diagnostics') } catch { /* Storage is optional. */ }
  }

  function updateSettings(newSettings: Partial<VoiceSettings>) {
    settings.value = { ...settings.value, ...newSettings }
    persistSettings()
  }

  function persistSettings() {
    localStorage.setItem('voiceSettings', JSON.stringify(settings.value))
  }

  function restoreSettings() {
    const stored = localStorage.getItem('voiceSettings')
    if (stored) {
      try {
        settings.value = { ...settings.value, ...JSON.parse(stored) }
      } catch {
        // Ignore invalid settings
      }
    }
  }

  function reset() {
    state.value = {
      isConnected: false,
      isConnecting: false,
      isMuted: false,
      isDeafened: false,
      currentChannel: null,
      peers: new Map(),
      localStream: null,
      microphoneWarning: null,
      volume: 1.0,
      noiseSuppressionEnabled: true,
      noiseSuppressionLevel: 0.5,
      spatialAudioEnabled: true,
    }
    connectionState.value = {
      peerId: 'local',
      iceConnectionState: 'new',
      connectionState: 'new',
      signalingState: 'stable',
      isMuted: false,
      isDeafened: false,
      volume: 1.0,
      position: undefined,
      lastActivity: Date.now(),
    }
  }

  // Channel methods
  async function joinChannel(channelId: string) {
    state.value.currentChannel = channelId
    // TODO: Implement actual channel join via signaling
  }

  async function leaveChannel() {
    state.value.currentChannel = null
    state.value.peers.clear()
    // TODO: Implement actual channel leave via signaling
  }

  async function createChannel(data: { name: string; position: Vec3; isPrivate: boolean }) {
    // TODO: Implement actual channel creation via signaling
    console.log('Creating channel:', data)
  }

  async function deleteChannel(channelId: string) {
    // TODO: Implement actual channel deletion via signaling
    console.log('Deleting channel:', channelId)
  }

  // Connection methods
  async function connect(options?:
    | { mode: 'server'; url: string; token: string; roomId: string; displayName: string }
    | { mode: 'peerjs'; pluginPeerId: string; host: string; port: number; path: string; secure: boolean; key: string; token: string; code: string }
  ) {
    state.value.isConnecting = true
    try {
      if (!options) throw new Error('Keine Voice-Server-Verbindung konfiguriert')
      serverConnection?.disconnect()
      peerJsConnection?.close()
      if (options.mode === 'peerjs') {
        let stream: MediaStream
        state.value.microphoneWarning = null
        try {
          stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false })
        } catch {
          addConnectionDiagnostic('Microphone unavailable or permission denied; using silent receive-only audio track')
          const silentAudio = createSilentAudioStream()
          stream = silentAudio.stream
          closeSilentAudio = silentAudio.close
          state.value.microphoneWarning = 'Kein Mikrofon verfügbar oder freigegeben. Du bist nur im Hörmodus; dein Mikrofon-Audio wird nicht übertragen.'
        }
        peerJsConnection = new PeerJsVoiceConnection({
          peerServer: { host: options.host, port: options.port, path: options.path, secure: options.secure, key: options.key, token: options.token },
          pluginPeerId: options.pluginPeerId,
          code: options.code,
          onDiagnostic: addConnectionDiagnostic,
          onTestChatState: connected => { testChatConnected.value = connected },
          onTestChatMessage: message => {
            testChatMessages.value.push({ ...message, id: `${Date.now()}-${Math.random()}`, receivedAt: Date.now() })
            if (testChatMessages.value.length > 500) testChatMessages.value.shift()
          },
          onState: connectionState => {
            updateConnectionState({ connectionState: connectionState === 'signaling' ? 'connecting' : connectionState })
            if (connectionState === 'connected') setConnected(true)
            else if (['failed', 'disconnected', 'closed'].includes(connectionState)) setConnected(false)
          },
          onStream: stream => {
            remoteAudio?.remove()
            remoteAudio = new Audio()
            remoteAudio.autoplay = true
            remoteAudio.srcObject = stream
            void remoteAudio.play()
          },
        })
        await peerJsConnection.connect(stream)
        setLocalStream(stream)
        setCurrentChannel('minecraft')
        setConnected(true)
        return
      }
      serverConnection = new ServerVoiceConnection({
        ...options,
        onState: connection => updateConnectionState({ connectionState: connection }),
      })
      const stream = await serverConnection.connect()
      setLocalStream(stream)
      setCurrentChannel(options.roomId)
      setConnected(true)
    } catch (error) {
      serverConnection?.disconnect()
      serverConnection = null
      peerJsConnection?.close()
      peerJsConnection = null
      state.value.isConnecting = false
      state.value.isConnected = false
      state.value.currentChannel = null
      state.value.localStream = null
      remoteAudio?.remove()
      remoteAudio = null
      closeSilentAudio?.()
      closeSilentAudio = null
      throw error
    }
  }

  async function disconnect() {
    serverConnection?.disconnect()
    serverConnection = null
    peerJsConnection?.close()
    peerJsConnection = null
    testChatConnected.value = false
    closeSilentAudio?.()
    closeSilentAudio = null
    remoteAudio?.remove()
    remoteAudio = null
    state.value.isConnected = false
    state.value.isConnecting = false
    state.value.currentChannel = null
    state.value.peers.clear()
    state.value.localStream = null
    state.value.microphoneWarning = null
    // TODO: Implement actual WebRTC disconnection
  }

  function sendTestChatMessage(message: string): boolean {
    const text = message.trim().slice(0, 256)
    return !!text && (peerJsConnection?.sendTestChat(text) ?? false)
  }

  // Device methods
  async function requestDevicePermissions() {
    try {
      await navigator.mediaDevices.getUserMedia({ audio: true, video: false })
    } catch {
      // Permission denied, but we still want to list devices
    }
  }

  async function updateInputDevices() {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices()
      const audioInputs = devices
        .filter(d => d.kind === 'audioinput')
        .map(d => ({
          deviceId: d.deviceId,
          label: d.label || `Microphone ${d.deviceId.slice(0, 8)}`,
          kind: 'audioinput' as const,
          groupId: d.groupId,
        }))
      availableInputDevices.value = audioInputs
      if (!settings.value.inputDeviceId && audioInputs.length > 0) {
        settings.value.inputDeviceId = audioInputs[0]?.deviceId ?? ''
      }
    } catch (err) {
      console.error('Failed to enumerate input devices:', err)
    }
  }

  async function updateOutputDevices() {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices()
      const audioOutputs = devices
        .filter(d => d.kind === 'audiooutput')
        .map(d => ({
          deviceId: d.deviceId,
          label: d.label || `Speaker ${d.deviceId.slice(0, 8)}`,
          kind: 'audiooutput' as const,
          groupId: d.groupId,
        }))
      availableOutputDevices.value = audioOutputs
      if (!settings.value.outputDeviceId && audioOutputs.length > 0) {
        settings.value.outputDeviceId = audioOutputs[0]?.deviceId ?? ''
      }
    } catch (err) {
      console.error('Failed to enumerate output devices:', err)
    }
  }

  return {
    state,
    settings,
    connectionState,
    availableInputDevices,
    availableOutputDevices,
    connectionDiagnostics,
    testChatMessages,
    testChatConnected,
    addConnectionDiagnostic,
    clearConnectionDiagnostics,
    connectedPeers,
    peerCount,
    isInChannel,
    setConnected,
    setConnecting,
    setMuted,
    setDeafened,
    setCurrentChannel,
    addPeer,
    removePeer,
    updatePeer,
    setLocalStream,
    setVolume,
    setNoiseSuppressionEnabled,
    setNoiseSuppressionLevel,
    setSpatialAudioEnabled,
    updateConnectionState,
    setInputDevices,
    setOutputDevices,
    updateSettings,
    persistSettings,
    restoreSettings,
    reset,
    // New methods
    joinChannel,
    leaveChannel,
    createChannel,
    deleteChannel,
    connect,
    disconnect,
    sendTestChatMessage,
    requestDevicePermissions,
    updateInputDevices,
    updateOutputDevices,
  }
})

function loadConnectionDiagnostics(): string[] {
  try {
    const stored = localStorage.getItem('svc-connection-diagnostics')
    const entries: unknown = stored ? JSON.parse(stored) : []
    return Array.isArray(entries) ? entries.filter((entry): entry is string => typeof entry === 'string').slice(-500) : []
  } catch { return [] }
}
