import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { User, AuthState } from '../types'
import { verifyVoiceCode } from '../auth/api'

export const useAuthStore = defineStore('auth', () => {
  const user = ref<User | null>(null)
  const token = ref<string | null>(null)
  const joinCode = ref<string | null>(null)
  const isLoading = ref(false)
  const error = ref<string | null>(null)

  const isAuthenticated = computed(() => !!token.value && !!user.value)
  const username = computed(() => user.value?.username ?? '')
  const userId = computed(() => user.value?.id ?? '')
  const hasJoinCode = computed(() => !!joinCode.value)

  function setAuth(authData: { user: User; token: string }) {
    user.value = authData.user
    token.value = authData.token
    error.value = null
    persistAuth()
  }

  function setJoinCode(code: string) {
    joinCode.value = code
    error.value = null
  }

  /** Starts the local PeerJS auth flow; the plugin validates the code itself. */
  function preparePeerJsAuth(code: string) {
    const normalizedCode = code.trim().toUpperCase()
    setJoinCode(normalizedCode)
    user.value = {
      id: 'peerjs-pending',
      username: 'Minecraft-Spieler',
      displayName: 'Minecraft-Spieler',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    }
    token.value = `peerjs:${normalizedCode}`
    error.value = null
  }

  function clearJoinCode() {
    joinCode.value = null
  }

  function clearAuth() {
    user.value = null
    token.value = null
    joinCode.value = null
    error.value = null
    localStorage.removeItem('auth')
    sessionStorage.removeItem('auth')
  }

  function setLoading(loading: boolean) {
    isLoading.value = loading
  }

  function setError(err: string | null) {
    error.value = err
  }

  function persistAuth() {
    if (token.value && user.value) {
      const authData = { user: user.value, token: token.value }
      localStorage.setItem('auth', JSON.stringify(authData))
    }
  }

  function restoreAuth() {
    const stored = localStorage.getItem('auth') ?? sessionStorage.getItem('auth')
    if (stored) {
      try {
        const authData = JSON.parse(stored)
        if (authData.user && authData.token) {
          if (typeof authData.token === 'string' && authData.token.startsWith('peerjs:')) {
            localStorage.removeItem('auth')
            sessionStorage.removeItem('auth')
            return
          }
          user.value = authData.user
          token.value = authData.token
        }
      } catch {
        clearAuth()
      }
    }
  }

  function updateUser(updates: Partial<User>) {
    if (user.value) {
      user.value = { ...user.value, ...updates }
      persistAuth()
    }
  }

  async function joinWithCode(code: string): Promise<{ user: User; token: string }> {
    setLoading(true)
    error.value = null
    try {
      const normalizedCode = code.toUpperCase()
      if (!/^[A-Z0-9]{5}$/.test(normalizedCode)) {
        throw new Error('Code muss 5-stellig und alphanumerisch sein')
      }

      const auth = await verifyVoiceCode(normalizedCode)
      const verifiedUser: User = {
        id: auth.playerUuid,
        username: auth.playerName,
        displayName: auth.playerName,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      }

      setAuth({ user: verifiedUser, token: auth.token })
      setJoinCode(normalizedCode)

      return { user: verifiedUser, token: auth.token }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Beitreten fehlgeschlagen'
      setError(message)
      throw err
    } finally {
      isLoading.value = false
    }
  }

  async function login(credentials: { username: string; password: string }): Promise<{ user: User; token: string }> {
    setLoading(true)
    error.value = null
    try {
      // TODO: Implement actual API call
      const mockUser: User = {
        id: '1',
        username: credentials.username,
        displayName: credentials.username,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      }
      const mockToken = 'mock-jwt-token-' + Date.now()
      setAuth({ user: mockUser, token: mockToken })
      return { user: mockUser, token: mockToken }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Login fehlgeschlagen'
      setError(message)
      throw err
    } finally {
      isLoading.value = false
    }
  }

  async function register(data: { username: string; password: string; displayName?: string }): Promise<{ user: User; token: string }> {
    setLoading(true)
    error.value = null
    try {
      // TODO: Implement actual API call
      const mockUser: User = {
        id: String(Date.now()),
        username: data.username,
        displayName: data.displayName ?? data.username,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      }
      const mockToken = 'mock-jwt-token-' + Date.now()
      setAuth({ user: mockUser, token: mockToken })
      return { user: mockUser, token: mockToken }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Registrierung fehlgeschlagen'
      setError(message)
      throw err
    } finally {
      isLoading.value = false
    }
  }

  return {
    user,
    token,
    joinCode,
    isLoading,
    error,
    isAuthenticated,
    username,
    userId,
    hasJoinCode,
    setAuth,
    setJoinCode,
    clearJoinCode,
    clearAuth,
    setLoading,
    setError,
    persistAuth,
    restoreAuth,
    updateUser,
    joinWithCode,
    preparePeerJsAuth,
    login,
    register,
  }
})
